        unordered_map<int, int> seen;
        for(int i = 0; i < (int)nums.size(); i++) {
            const int need = target - nums[i];
            if(seen.count(need)) {
                return {seen[need], i};
            }
            seen[nums[i]] = i;
        }
        return {};
    }

